// The tagged handles are generated by macro: four buffer-access tags on
// `mmap`, plus the sized `mmaps`. These pin the shape the macro is expected
// to produce -- in particular that `vectorized()` and `reinterpret()` keep
// the tag rather than decaying to the untagged base.

template <typename Tagged, typename Base>
void CheckTagIsPreserved() {
  static_assert(std::is_base_of<Base, Tagged>::value,
                "a tagged handle must extend its untagged kind");
  static_assert(std::is_convertible<Base, Tagged>::value,
                "a tagged handle must be constructible from its untagged kind");
}

TEST(TaggedMmapTest, EveryTagExtendsItsKind) {
  CheckTagIsPreserved<placeholder_mmap<int>, mmap<int>>();
  CheckTagIsPreserved<read_only_mmap<int>, mmap<int>>();
  CheckTagIsPreserved<write_only_mmap<int>, mmap<int>>();
  CheckTagIsPreserved<read_write_mmap<int>, mmap<int>>();
}

TEST(TaggedMmapTest, VectorizedAndReinterpretKeepTheTag) {
  std::vector<int> buffer(16);

  read_only_mmap<int> ro(buffer);
  static_assert(std::is_same<decltype(ro.vectorized<2>()),
                             read_only_mmap<vec_t<int, 2>>>::value,
                "vectorized() must stay read_only");
  static_assert(std::is_same<decltype(ro.reinterpret<char>()),
                             read_only_mmap<char>>::value,
                "reinterpret() must stay read_only");

  write_only_mmap<int> wo(buffer);
  static_assert(std::is_same<decltype(wo.reinterpret<int64_t>()),
                             write_only_mmap<int64_t>>::value,
                "reinterpret() must stay write_only");

  // The generated wrappers forward to the base, so the view still describes
  // the same memory.
  EXPECT_EQ(ro.size(), buffer.size());
  EXPECT_EQ(ro.vectorized<2>().size(), buffer.size() / 2);
  EXPECT_EQ(wo.reinterpret<int64_t>().size(),
            buffer.size() * sizeof(int) / sizeof(int64_t));
}

TEST(TaggedMmapTest, SizedMmapsKeepTheTagAndTheCount) {
  static_assert(std::is_base_of<mmaps<int, 4>, read_only_mmaps<int, 4>>::value,
                "a tagged mmaps must extend its untagged kind");
  static_assert(std::is_same<decltype(std::declval<read_only_mmaps<int, 4>>()
                                          .template vectorized<2>()),
                             read_only_mmaps<vec_t<int, 2>, 4>>::value,
                "vectorized() must keep both the tag and the channel count");
}

TEST(MmapsTest, SlicesPreserveRegionsAndIncludeTheLastChannel) {
  std::array<std::vector<int>, 4> buffers = {
      std::vector<int>{10}, std::vector<int>{20, 21},
      std::vector<int>{30, 31, 32}, std::vector<int>{40, 41, 42, 43}};
  mmaps<int, 4> memory(buffers);

  auto middle = memory.slice<1, 2>();
  auto tail = memory.slice<2, 2>();
  auto whole = memory.slice<0, 4>();
  for (int i = 0; i < 2; ++i) {
    EXPECT_EQ(middle[i].data(), buffers[i + 1].data());
    EXPECT_EQ(middle[i].size(), buffers[i + 1].size());
    EXPECT_EQ(tail[i].data(), buffers[i + 2].data());
    EXPECT_EQ(tail[i].size(), buffers[i + 2].size());
  }
  for (int i = 0; i < 4; ++i) {
    EXPECT_EQ(whole[i].data(), buffers[i].data());
    EXPECT_EQ(whole[i].size(), buffers[i].size());
  }
  tail[1][2] = 99;
  EXPECT_EQ(buffers[3][2], 99);
}

// Stands in for frt::Instance: records the buffers an accessor binds.
struct BufferRecorder {
  struct Buffer {
    int index;
    const void* ptr;
    size_t bytes;
    BufferAccess access;
  };
  std::vector<Buffer> buffers;

  void SetBufferArg(int index, const void* ptr, size_t bytes,
                    BufferAccess access) {
    buffers.push_back({index, ptr, bytes, access});
  }
};

// With a bitstream the kernel reads every channel of an hmap, so a short
// buffer must fail the same size check as in software simulation rather
// than be read past its end.
TEST(HmapAccessorDeathTest, BitstreamChecksTheSize) {
  std::vector<int> buffer(7);
  BufferRecorder instance;
  int idx = 0;
  EXPECT_DEATH(
      (internal::accessor<hmap<int, 2, 4>, read_only_mmap<int>>::access(
          instance, idx, read_only_mmap<int>(buffer))),
      "hmap<T, 2, 4> must have size = 8, got 7");
}

// A named untagged mmap binds to an hmap parameter as it does to an mmap
// one: read-write, here one buffer per channel.
TEST(HmapAccessorTest, NamedMmapBindsEachChannelReadWrite) {
  std::vector<int> buffer(8);
  mmap<int> mem(buffer);
  using Accessor = internal::accessor<hmap<int, 2, 4>, mmap<int>&>;
  EXPECT_EQ(Accessor::access(mem).data(), buffer.data());

  BufferRecorder instance;
  int idx = 0;
  Accessor::access(instance, idx, mem);
  EXPECT_EQ(idx, 2);
  ASSERT_EQ(instance.buffers.size(), 2u);
  for (int i = 0; i < 2; ++i) {
    EXPECT_EQ(instance.buffers[i].index, i);
    EXPECT_EQ(instance.buffers[i].ptr, buffer.data() + 4 * i);
    EXPECT_EQ(instance.buffers[i].bytes, 4 * sizeof(int));
    EXPECT_EQ(instance.buffers[i].access, BufferAccess::ReadWrite);
  }
}

// A read-only parameter binds the kernel the same buffer, with the same
// access, as a parameter of the writable type would; never as a scalar.
TEST(MmapAccessorTest, ReadOnlyParameterBindsTheWritableBuffer) {
  std::vector<int> buffer(3);
  read_only_mmap<int> named(buffer);
  mmap<int> untagged(buffer);
  BufferRecorder instance;
  int idx = 0;
  internal::accessor<mmap<const int>, read_only_mmap<int>>::access(
      instance, idx, read_only_mmap<int>(buffer));
  internal::accessor<mmap<const int>, read_only_mmap<int>&>::access(instance,
                                                                    idx, named);
  internal::accessor<mmap<const int>, mmap<int>&>::access(instance, idx,
                                                          untagged);
  EXPECT_EQ(idx, 3);
  ASSERT_EQ(instance.buffers.size(), 3u);
  const BufferAccess expected[] = {
      BufferAccess::ReadOnly, BufferAccess::ReadOnly, BufferAccess::ReadWrite};
  for (int i = 0; i < 3; ++i) {
    EXPECT_EQ(instance.buffers[i].index, i);
    EXPECT_EQ(instance.buffers[i].ptr, buffer.data());
    EXPECT_EQ(instance.buffers[i].bytes, 3 * sizeof(int));
    EXPECT_EQ(instance.buffers[i].access, expected[i]);
  }
  EXPECT_EQ((internal::accessor<mmap<const int>, mmap<int>&>::access(untagged)
                 .data()),
            buffer.data());
}

// An async_mmap moves data only through its channels: a pointer step would
// move a copy of the pointer that the channels never see, so it must not
// compile, while the plain mmap it extends keeps its steps.
template <typename T, typename = void>
struct PreIncrements : std::false_type {};
template <typename T>
struct PreIncrements<T, std::void_t<decltype(++std::declval<T&>())>>
    : std::true_type {};
template <typename T, typename = void>
struct PreDecrements : std::false_type {};
template <typename T>
struct PreDecrements<T, std::void_t<decltype(--std::declval<T&>())>>
    : std::true_type {};
template <typename T, typename = void>
struct PostIncrements : std::false_type {};
template <typename T>
struct PostIncrements<T, std::void_t<decltype(std::declval<T&>()++)>>
    : std::true_type {};
template <typename T, typename = void>
struct PostDecrements : std::false_type {};
template <typename T>
struct PostDecrements<T, std::void_t<decltype(std::declval<T&>()--)>>
    : std::true_type {};

static_assert(PreIncrements<mmap<int>>::value &&
                  PreDecrements<mmap<int>>::value &&
                  PostIncrements<mmap<int>>::value &&
                  PostDecrements<mmap<int>>::value,
              "mmap steps its pointer");
static_assert(!PreIncrements<async_mmap<int>>::value &&
                  !PreDecrements<async_mmap<int>>::value &&
                  !PostIncrements<async_mmap<int>>::value &&
                  !PostDecrements<async_mmap<int>>::value,
              "async_mmap rejects pointer steps");

